using System.Text;using System.Windows;using ESD.Infrastructure;using ESD.Protocol;
namespace ESD.Wpf;
public partial class MainWindow:Window{readonly SerialTransport s=new();readonly FrameStreamParser p=new();uint seq=1;int good,bad;public MainWindow(){InitializeComponent();Bauds.ItemsSource=new[]{9600,19200,38400,57600,115200};Bauds.SelectedItem=115200;RefreshPorts();s.Data+=(_,d)=>Dispatcher.Invoke(()=>{LogMsg("RX",FrameCodec.ToHex(d));p.Push(d);});s.Error+=(_,m)=>Dispatcher.Invoke(()=>LogMsg("ERROR",m));p.Frame+=d=>Dispatcher.Invoke(()=>Parse(d));}void RefreshPorts(){Ports.ItemsSource=SerialTransport.Ports();if(Ports.Items.Count>0)Ports.SelectedIndex=0;}void Refresh(object?o,RoutedEventArgs e)=>RefreshPorts();void Connect(object?o,RoutedEventArgs e){try{if(Ports.SelectedItem is not string port){LogMsg("ERROR","Select COM port");return;}s.Open(port,(int)Bauds.SelectedItem!);Conn.Text="Connected "+port;LogMsg("SYS","Connected");}catch(Exception x){LogMsg("ERROR",x.Message);}}void Disconnect(object?o,RoutedEventArgs e){s.Close();Conn.Text="Disconnected";LogMsg("SYS","Disconnected");}byte[] K()=>FrameCodec.FromHex(Key.Text);void Send(Command c,byte[] data){try{uint id=uint.TryParse(Dev.Text,out var x)?x:1;var f=new EsdFrame(1,FrameFlags.AckRequested,id,c,seq++,(uint)DateTimeOffset.UtcNow.ToUnixTimeSeconds(),data,Array.Empty<byte>());var raw=FrameCodec.Encode(f,K());s.Write(raw);LogMsg("TX",FrameCodec.ToHex(raw));}catch(Exception x){LogMsg("ERROR",x.Message);}}void WorkerScan(object?o,RoutedEventArgs e)=>Send(Command.WorkerScan,Encoding.UTF8.GetBytes(Worker.Text));void Heartbeat(object?o,RoutedEventArgs e)=>Send(Command.Heartbeat,Array.Empty<byte>());void SendRaw(object?o,RoutedEventArgs e){try{s.Write(FrameCodec.FromHex(Raw.Text));}catch(Exception x){LogMsg("ERROR",x.Message);}}void Parse(byte[] raw){if(FrameCodec.TryDecode(raw,K(),out var f,out var e)&&f!=null){good++;Valid.Text=good.ToString();Last.Text=f.Command.ToString();LogMsg("VALID",$"CMD={f.Command} DEV={f.DeviceId} SEQ={f.Sequence} DATA={Encoding.UTF8.GetString(f.Payload)}");}else{bad++;Bad.Text=bad.ToString();LogMsg("BAD",e.ToString());}}void LogMsg(string a,string b){Log.Items.Insert(0,$"{DateTime.Now:HH:mm:ss.fff} [{a}] {b}");while(Log.Items.Count>500)Log.Items.RemoveAt(Log.Items.Count-1);}}
